{"code": "import pytest
import impl


# Core ALLOW/DENY behavior
def test_allow_path():
    """A request matching an ALLOW policy returns ALLOW."""
    request = {'subject': 'alice', 'roles': [], 'action': 's3:GetObject', 'resource': 'docs/reports/Q1'}
    policies = [{'effect': 'ALLOW', 'principal': 'user:alice', 'action': 's3:GetObject', 'resource': 'docs/reports/Q1'}]
    assert impl.authorize(request, policies) == 'ALLOW'


def test_deny_path():
    """A request matching a DENY policy returns DENY."""
    request = {'subject': 'alice', 'roles': [], 'action': 's3:GetObject', 'resource': 'docs/reports/Q1'}
    policies = [{'effect': 'DENY', 'principal': 'user:alice', 'action': 's3:GetObject', 'resource': 'docs/reports/Q1'}]
    assert impl.authorize(request, policies) == 'DENY'


def test_default_deny_no_match():
    """No matching policies defaults to DENY."""
    request = {'subject': 'alice', 'roles': [], 'action': 's3:GetObject', 'resource': 'docs/reports/Q1'}
    policies = [{'effect': 'ALLOW', 'principal': 'user:bob', 'action': 's3:GetObject', 'resource': 'docs/reports/Q1'}]
    assert impl.authorize(request, policies) == 'DENY'


def test_deny_overrides_allow():
    """Matching DENY overrides matching ALLOW (deny-overrides)."""
    request = {'subject': 'alice', 'roles': ['contractor'], 'action': 's3:GetObject', 'resource': 'docs/reports/Q1'}
    policies = [
        {'effect': 'ALLOW', 'principal': 'user:alice', 'action': '*', 'resource': '*'},
        {'effect': 'DENY', 'principal': 'role:contractor', 'action': 's3:*', 'resource': 'docs/reports/*'}
    ]
    assert impl.authorize(request, policies) == 'DENY'


def test_deny_overrides_regardless_of_order():
    """DENY overrides ALLOW regardless of position in list."""
    request = {'subject': 'alice', 'roles': ['contractor'], 'action': 's3:GetObject', 'resource': 'docs/reports/Q1'}
    policies = [
        {'effect': 'DENY', 'principal': 'role:contractor', 'action': 's3:*', 'resource': 'docs/reports/*'},
        {'effect': 'ALLOW', 'principal': 'user:alice', 'action': '*', 'resource': '*'}
    ]
    assert impl.authorize(request, policies) == 'DENY'


def test_multiple_allows():
    """Multiple matching ALLOWs return ALLOW."""
    request = {'subject': 'alice', 'roles': ['admin'], 'action': 's3:GetObject', 'resource': 'docs/reports/Q1'}
    policies = [
        {'effect': 'ALLOW', 'principal': 'user:alice', 'action': 's3:*', 'resource': '*'},
        {'effect': 'ALLOW', 'principal': 'role:admin', 'action': '*', 'resource': 'docs/reports/*'}
    ]
    assert impl.authorize(request, policies) == 'ALLOW'


# Request validation
def test_request_missing_fields():
    """Request missing required fields raises ValueError."""
    request = {'subject': 'alice', 'roles': [], 'action': 's3:GetObject'}
    with pytest.raises(ValueError, match="Request missing required fields"):
        impl.authorize(request, [])


def test_roles_not_list():
    """Request with non-list roles raises ValueError."""
    request = {'subject': 'alice', 'roles': 'contractor', 'action': 's3:GetObject', 'resource': 'docs/reports/Q1'}
    with pytest.raises(ValueError, match="'roles' must be a list"):
        impl.authorize(request, [])


# Policy validation
def test_policy_missing_fields():
    """Policy missing required fields raises ValueError."""
    request = {'subject': 'alice', 'roles': [], 'action': 's3:GetObject', 'resource': 'docs/reports/Q1'}
    policies = [{'effect': 'ALLOW', 'principal': 'user:alice', 'action': 's3:GetObject'}]
    with pytest.raises(ValueError, match="Policy missing required fields"):
        impl.authorize(request, policies)


def test_invalid_effect_with_value_in_message():
    """Invalid effect raises ValueError with the offending value."""
    request = {'subject': 'alice', 'roles': [], 'action': 's3:GetObject', 'resource': 'docs/reports/Q1'}
    policies = [{'effect': 'Allow', 'principal': 'user:alice', 'action': 's3:GetObject', 'resource': 'docs/reports/Q1'}]
    with pytest.raises(ValueError, match="Invalid effect: 'Allow'"):
        impl.authorize(request, policies)


# Principal matching
def test_user_principal():
    """User principal matches exact subject."""
    request = {'subject': 'alice', 'roles': [], 'action': 's3:GetObject', 'resource': 'docs/reports/Q1'}
    policies = [{'effect': 'ALLOW', 'principal': 'user:alice', 'action': 's3:GetObject', 'resource': 'docs/reports/Q1'}]
    assert impl.authorize(request, policies) == 'ALLOW'


def test_role_principal():
    """Role principal matches when role in request."""
    request = {'subject': 'alice', 'roles': ['contractor'], 'action': 's3:GetObject', 'resource': 'docs/reports/Q1'}
    policies = [{'effect': 'ALLOW', 'principal': 'role:contractor', 'action': 's3:GetObject', 'resource': 'docs/reports/Q1'}]
    assert impl.authorize(request, policies) == 'ALLOW'


def test_wildcard_principal():
    """Wildcard principal '*' matches any principal."""
    request = {'subject': 'anyone', 'roles': [], 'action': 's3:GetObject', 'resource': 'docs/reports/Q1'}
    policies = [{'effect': 'ALLOW', 'principal': '*', 'action': 's3:GetObject', 'resource': 'docs/reports/Q1'}]
    assert impl.authorize(request, policies) == 'ALLOW'


def test_user_principal_with_literal_star():
    """User principal 'user:al*' is literal, doesn't match 'alice'."""
    request = {'subject': 'alice', 'roles': [], 'action': 's3:GetObject', 'resource': 'docs/reports/Q1'}
    policies = [{'effect': 'ALLOW', 'principal': 'user:al*', 'action': 's3:GetObject', 'resource': 'docs/reports/Q1'}]
    assert impl.authorize(request, policies) == 'DENY'


# Action and resource prefix matching
def test_action_prefix_match():
    """Action with trailing '*' matches as prefix."""
    request = {'subject': 'alice', 'roles': [], 'action': 's3:GetObject', 'resource': 'docs/reports/Q1'}
    policies = [{'effect': 'ALLOW', 'principal': '*', 'action': 's3:Get*', 'resource': '*'}]
    assert impl.authorize(request, policies) == 'ALLOW'


def test_resource_prefix_match():
    """Resource with trailing '*' matches as prefix."""
    request = {'subject': 'alice', 'roles': [], 'action': 's3:GetObject', 'resource': 'docs/reports/Q1'}
    policies = [{'effect': 'ALLOW', 'principal': '*', 'action': '*', 'resource': 'docs/reports/*'}]
    assert impl.authorize(request, policies) == 'ALLOW'


def test_resource_prefix_boundary():
    """'docs/reports/*' does not match 'docs/reportsQ1' (critical boundary case)."""
    request = {'subject': 'alice', 'roles': [], 'action': 's3:GetObject', 'resource': 'docs/reportsQ1'}
    policies = [{'effect': 'ALLOW', 'principal': '*', 'action': '*', 'resource': 'docs/reports/*'}]
    assert impl.authorize(request, policies) == 'DENY'


def test_nonfinal_star_is_literal():
    """Non-final '*' in action is literal, not a wildcard."""
    request = {'subject': 'alice', 'roles': [], 'action': 's3:GetObject', 'resource': 'docs/reports/Q1'}
    policies = [{'effect': 'ALLOW', 'principal': '*', 'action': 's3:*Object', 'resource': '*'}]
    assert impl.authorize(request, policies) == 'DENY'


# Edge cases
def test_empty_policies_list():
    """Empty policies list defaults to DENY."""
    request = {'subject': 'alice', 'roles': [], 'action': 's3:GetObject', 'resource': 'docs/reports/Q1'}
    assert impl.authorize(request, []) == 'DENY'


def test_validation_before_deciding():
    """All policies validated before any matching/decision."""
    request = {'subject': 'alice', 'roles': [], 'action': 's3:GetObject', 'resource': 'docs/reports/Q1'}
    policies = [
        {'effect': 'ALLOW', 'principal': 'user:alice', 'action': 's3:GetObject', 'resource': 'docs/reports/Q1'},
        {'effect': 'INVALID', 'principal': 'user:bob', 'action': 's3:GetObject', 'resource': 'docs/reports/Q1'}
    ]
    with pytest.raises(ValueError, match="Invalid effect: 'INVALID'"):
        impl.authorize(request, policies)
"}
